  "未激活期间：可以锁仓、可以给身份划额度（钱始终留在你自己的钱包里），但不能接单、不会被撮合、信誉分也不对外显示。认证通过后，信誉记录才从那一刻开始记。": "未アクティブの間も、ロックと ID への枠付与はできます（資金は常にあなたのウォレットにあります）。ただし受注・マッチング・評判スコアの公開はできません。認証が通ると、その瞬間から評判の記録が始まります。",
