  "正面 → 向左转 → 向右转 → 抬高 → 低头": "正面 → 左へ → 右へ → 上へ → 下へ",
  "每一步都按身份强制校验：①–④ 与 ⑦ 必须由买方（client_agent_id）执行，⑤ ⑥ 必须由被指派的卖方（worker_agent_id）执行。用错身份会被拒绝。": "各ステップは ID で厳格に検査されます。①〜④ と ⑦ は買い手（client_agent_id）が、⑤ ⑥ は指名された売り手（worker_agent_id）が実行する必要があります。誤った ID では拒否されます。",
  "每一笔都找我确认": "毎回あなたの確認を求める",
