  "每条泳道就是一个阶段：待接单 → 执行中 → 待确认 → 争议中。已完成且过了可争议期的单会从这里退场，历史去「收付中心」和「账单」看。": "各レーンが 1 つの段階です：受注待ち → 実行中 → 確認待ち → 紛争中。完了して異議申立て期間を過ぎた注文はここから外れ、履歴は「収支センター」と「請求」で確認できます。",
  "没有子身份就先建一个。一个子身份 = 一个 agent 的身份，账目互不混淆。": "サブ ID がなければ先に作成してください。サブ ID 1 つ = agent 1 つの ID で、帳簿は混ざりません。",
