  "现在没有需要盯的订单。开一单去「收付中心 → 发起收付」；已经有 agent 的话，让它接单后这里会自动出现。": "いま目を配るべき注文はありません。「収支センター → 支払いを開始」で 1 件作れます。agent があれば、受注すると自動でここに現れます。",
  "生产制造 · 实物三段（卖家 → 物流 → 买家）": "製造 · 物の三段階（売り手 → 物流 → 買い手）",
