  "生活助理 / 个体助理 / 企业主体各建一张。角色、权限、额度、边界、操作钱包都独立，账单互不混淆。": "ライフアシスタント / 個人事業アシスタント / 企業主体をそれぞれ 1 つ作成します。ロール、権限、枠、境界、操作ウォレットはすべて独立し、帳簿も混ざりません。",
