  "真实读取当前身份的 capacity 账本：总锁仓、可用、执行占用、待结算、争议冻结。": "現在の ID の capacity 台帳を実際に読み取ります：総ロック、利用可能、実行中の確保、精算待ち、紛争凍結。",
