  "真实走通 create → pending → lock → start → submit → buyer-accept（需先建任务合同）。": "実際に create → pending → lock → start → submit → buyer-accept を通します（先にタスク契約の作成が必要です）。",
  "确认区": "確認エリア",
  "确认对方的凭证真实、已锁定": "相手の証憑が本物でロック済みであることを確認",
