  "算力": "計算資源",
  "管理员只能暂停，不能改账、不能提现。所有责任额度永远 1:1 锚定 USDC。": "管理者は停止しかできず、帳簿の改変も出金もできません。すべての責任枠は常に USDC に 1:1 で紐づきます。",
