  "给每个子身份单独授权额度，总和不超过总锁仓；每个子身份在授权额度内行事，账单互不混淆。": "サブ ID ごとに個別に枠を付与し、合計は総ロックを超えません。各サブ ID は付与枠の範囲で動き、帳簿は混ざりません。",
