  "自主下单": "自分で発注",
  "自动同步": "自動同期",
  "自己去找能办事的人 / 商家": "仕事をしてくれる人 / 店を自分で探す",
  "自检只读、不改状态：先看一遍机器能查的（信用代码校验位、邮箱 MX、官网控制权），再决定要不要提交。": "読み取り専用のセルフチェックで状態は変えません。まず機械が確認できる項目（信用コードの検査数字、メール MX、ドメイン管理権）を洗い出してから、提出するか決められます。",
  "自检只读、不改状态：字号、经营者、经营范围、经营地址、联系邮箱先过一遍机器能查的。": "読み取り専用のセルフチェックで状態は変えません。屋号、事業主、事業範囲、所在地、連絡先メールを先に機械でチェックします。",
  "自然人认证：这是「我本人是谁」。文件在你自己的浏览器里加密后才上传 —— Karma 只拿到密文和摘要，看不到证件内容，全程不碰你的私钥、助记词。": "自然人認証は「私自身が誰か」を示します。ファイルはあなたのブラウザ内で暗号化してから送信されるため、Karma は暗号文とダイジェストしか受け取らず、書類の中身も、秘密鍵やシードフレーズも見ません。",
  "至少一份营业执照": "事業許可証が最低 1 枚",
  "营业执照": "事業許可証",
  "营业执照必传；ICP 备案、数据来源授权、对公账户证明可选。每份文件单独加密上传，服务端只存摘要。": "事業許可証は必須、ICP 届出・データソース認可・法人口座の証明は任意です。各ファイルは個別に暗号化して送信し、サーバーはダイジェストのみ保存します。",
  "营业执照必传；食品经营许可、特种行业许可、摊位证明可选。每份文件单独加密上传，服务端只存摘要与密文。": "事業許可証は必須、食品営業許可・特定業種許可・出店場所の証明は任意です。各ファイルは個別に暗号化して送信し、サーバーはダイジェストと暗号文のみ保存します。",
