  "还没接或还没开工": "まだ受注していない・未着手",
  "还没有加入资质。营业执照必传。": "まだ資料がありません。事業許可証は必須です。",
  "还没有子身份。给每个 agent 建一个子身份（生活助理 / 工作助理 / 企业助理），额度、权限和账单互不混淆 —— 点右上「+ 新建子身份」。": "まだサブ ID がありません。agent ごとに 1 つ作成してください（ライフ / ワーク / 企業アシスタント）。枠・権限・帳簿が混ざりません —— 右上の「+ 新しいサブ ID を作成」を押してください。",
  "还没有子身份可分额度。先建一个（生活助理 / 个体助理 / 企业主体），再回来这里划额度。": "枠を付与できるサブ ID がありません。先に 1 つ作成して（ライフアシスタント / 個人事業アシスタント / 企業主体）、ここに戻って枠を割り当ててください。",
  "还没有子身份档案，可在「身份」页创建。": "サブ ID プロフィールがまだありません。「ID」ページで作成できます。",
  "还没有子身份，先新建一个": "サブ ID がまだありません。先に作成してください",
  "还没有支出记录。发起付款授权或接单后，这里会按状态列出每一笔。": "支出記録はまだありません。支払い認可を出したか受注すると、ここに状態ごとに並びます。",
  "还没有收入记录。你作为卖方接单结算后，这里会按状态列出每一笔。": "収入記録はまだありません。売り手として受注し精算すると、ここに状態ごとに並びます。",
  "还没有资质 —— 企业主体至少要有营业执照。": "資料がまだありません —— 企業主体には事業許可証が最低 1 枚必要です。",
  "还没有身份档案，请先在「身份档案管理」创建": "ID プロフィールがまだありません。先に「ID プロフィール管理」で作成してください",
  "还没有锁仓": "まだロックしていません",
  "这一块是「这个个体经营是谁、卖什么、在哪」，对外公开，买家能看到。": "このブロックは「この個人事業が誰で、何を売り、どこにあるか」を示します。公開情報で、買い手も見られます。",
  "这个 agent 用哪个身份": "この agent が使う ID",
  "这个分类下暂时没有待办。": "このカテゴリに未処理はありません。",
  "这个身份下还没有开发者实名档案。填好①的姓名与职务，点「生成待签协议」→「钱包签名并提交」。": "この ID にはまだ開発者実名プロフィールがありません。① の氏名と役職を入力し、「署名用の契約書を生成」→「ウォレット署名で送信」を押してください。",
  "这里的每一个技能都是一个真实可调用的 endpoint。单价、累计到多少才结算，全部由提供方的钱包签名背书 —— Karma 不替任何人定价。": "ここにあるスキルはすべて実際に呼び出せる endpoint です。単価も精算のしきい値も、提供者のウォレット署名が裏付けます —— Karma は誰の価格も決めません。",
