  "2. 保存服务端策略（PUT /v1/identities/{id}/automation-policy）": "2. サーバー側ポリシーを保存します（PUT /v1/identities/{id}/automation-policy）",
  "3. 钱包签名铸造 Runtime Key（不得超过已保存策略）": "3. ウォレット署名で Runtime Key を発行します（保存済みポリシーを超えてはいけません）",
