  "6. 导出 handoff JSON 交给 OpenClaw（MCP 将校验存证）": "6. handoff JSON をエクスポートして OpenClaw に渡します（MCP が証跡を検証します）",
  "单笔 ≤ {0} USDC：我可以自己挑商家、自己下单，不用问你": "1 件 ≤ {0} USDC：商家選びと発注は自分で行い、あなたに確認しません",
  "取消 / 退款 / 改价 / 换商家 我永远不会自己做，必须等你确认": "キャンセル / 返金 / 価格変更 / 商家変更は絶対に自分では行わず、あなたの確認を待ちます",
  "自动下单未开启：每一笔都要主人在操作台确认": "自動発注はオフです：毎回オーナーがコンソールで確認する必要があります",
  "单笔 > {0} USDC 会被直接拒绝（Runtime Key 硬上限）": "1 件が {0} USDC を超えると即座に拒否されます（Runtime Key のハード上限）",
  "每天累计上限 {0} USDC，今天已用 {1} USDC": "1 日の累計上限 {0} USDC、本日使用済み {1} USDC",
  "主人要求每一笔都人工确认": "オーナーは毎回の手動確認を求めています",
  "还没保存自动授权策略：只能读状态，不能自动花钱": "自動授权ポリシーが未保存です：状態の読み取りのみ可能で、自動で支払うことはできません",
  "能力/责任/确认边界已界定：Agent 只在 must_confirm 步骤询问主人是否确认；auto_ok 步骤自动执行，保证交付畅通与增效。": "能力・責任・確認の境界を画定しました：Agent は must_confirm のステップでのみオーナーに確認し、auto_ok のステップは自動で実行して納品を円滑にし効率を高めます。",
  "边界不完整：对端可见缺口。建议走 connect-from-template 补齐 service_specs 与不做清单。": "境界が不完全です：相手側にギャップが見えています。connect-from-template で service_specs と「やらないこと」リストを補ってください。",
  "交付与证据责任在本 agent；资金不托管；转委托默认关闭；成交字段另走 Important Fields 三方锁定。": "納品と証跡の責任は本 agent にあります。資金は預託しません。再委託は既定でオフです。成約フィールドは Important Fields の三者ロックで確定します。",
  "用 agent 私钥对 canonical_message 做 Ed25519 签名，填入 ownership_proof": "agent の秘密鍵で canonical_message に Ed25519 署名し、ownership_proof に入力します",
  "已写入目录。若 p1_ready=false，对端核验将拒绝将其视为可履约商家；请走 connect-from-template 补齐身份/责任/履约能力。": "ディレクトリに書き込みました。p1_ready=false の場合、相手側の検証はこれを履行可能な商家とみなしません。connect-from-template でアイデンティティ・責任・履行能力を補ってください。",
  "P1 接入完成：身份类别、主人绑定、履约能力与责任签认已落库。": "P1 接続が完了しました：アイデンティティ区分、オーナー紐付け、履行能力、責任の署名がすべて登録されました。",
  "一键接入完成：已按垂直场景落库身份/边界/责任签认，并签发引导 API Key（仅此一次明文）。": "ワンクリック接続が完了しました：業種ごとにアイデンティティ・境界・責任の署名を登録し、初期 API Key を発行しました（平文は今回のみ）。",
  "接入完成：身份卡 → agent 已绑定，责任签认与履约边界已落库。": "接続が完了しました：アイデンティティカード → agent を紐付け、責任署名と履行境界を登録しました。",
  "agent 已停用；Karma 托管的运行密钥已销毁，API Key 不再可通过鉴权。": "agent は無効化されました。Karma が保管していた実行キーは破棄され、API Key は認証を通らなくなりました。",
  "公开侧为聚合与承诺哈希；明细金额/身份仅密文可查": "公開側は集計とコミットメントハッシュのみです。明細の金額・身元は暗号文でのみ確認できます",
  "公开字段仅为承诺哈希与场景/结果；金额与当事人身份在 karma2 密文中，持 parties/regulator 角色密钥可解密审计": "公開フィールドはコミットメントハッシュとシーン・結果のみです。金額と当事者の身元は karma2 の暗号文にあり、parties/regulator ロール鍵を持つ者が復号して監査できます",
  "公开可核验承诺完整性；不含金额明文": "コミットメントの完全性は公開検証可能です。金額の平文は含みません",
  "解密仅供当事人或监管审计；禁止将明文写入公开索引": "復号は当事者または規制当局の監査に限ります。平文を公開インデックスに書き込むことは禁止です",
  "Agent 可在验真通过后代用户完成结算确认，节省时间": "検証が通れば、Agent がユーザーの代わりに決済確認を完了でき、時間を節約できます",
  "本场景要求主人显式确认或验真未完成，禁止 Agent 代结算": "このシーンではオーナーの明示的な確認が必要か、検証が未完了です。Agent が代理で決済することはできません",
  "卖方确认接单后违约赔偿责任生效；责任金 {0} bps，补偿 {1} bps": "売り手が受注を確認すると违约賠償責任が発効します。責任金 {0} bps、補償 {1} bps",
