  "可重新发现匹配其他商家": "再ディスカバリで別の商家を探せます",
  "本次意向已取消；请重新发起": "この意向はキャンセルされました。新しく作成してください",
  "本次意向已因卖方超时取消；请重新发现匹配": "売り手のタイムアウトによりこの意向はキャンセルされました。再ディスカバリしてください",
  "卖方边界未通过 P2 核验：未声明场景、确认策略被放宽、或 P1 未就绪。安全优先，拒绝履约。": "売り手の境界が P2 検証を通りませんでした：シーン未申告、確認ポリシーの緩和、または P1 未準備です。安全優先のため履行を拒否します。",
  "商家需 connect-from-template + responsibility_ack 后重试": "商家は connect-from-template + responsibility_ack の後に再試行してください",
