  "数字/行程场景验真通过": "デジタル・行程シーンの検証に合格しました",
  "静默窗已过但链路未通过: {0} — 不默认确认": "静黙期間を過ぎましたがチェーンが通りませんでした: {0} — 既定では確認しません",
  "买方超时未确认；已校验卖方发出+物流接件/送达凭证正确 → 默认确认": "買い手が期限内に確認しませんでした。売り手の発送と物流の受領・配達証跡が正しいことを検証済み → 既定で確認扱い",
  "使用全局默认确认策略（未知 scene，勿用于高风险成交）": "グローバル既定の確認ポリシーを使用します（未知の scene。高リスク成約には使用しないでください）",
  "需主人确认 {0} 步；可自动 {1} 步。Agent 只需在必须确认点询问是否确认。": "オーナーの確認が必要なのは {0} ステップ、自動実行できるのは {1} ステップです。Agent は必須確認ポイントでのみ確認します。",
  "主人已确认，Agent 可继续接单/锁字段/执行/结算": "オーナーが確認しました。Agent は受注・フィールドのロック・実行・決済を続行できます",
  "主人已拒绝，停止该步，不接单、不锁款": "オーナーが拒否しました。このステップで停止し、受注も資金ロックも行いません",
  "主身份本人实名认证：证件 + 刷脸": "主アイデンティティ本人の実名認証：身分証 + 顔認証",
  "已激活：信誉记录从现在开始记，可以接单、可以被撮合。": "有効化済み：評判記録はここから始まり、受注とマッチングが可能です。",
  "未激活：主身份本人完成「证件 + 刷脸」认证后自动激活，信誉记录才会开始记；未激活期间可以锁仓、可以给身份划额度，但不能接单、不能被撮合。": "未激活：主アイデンティティ本人が「身分証 + 顔認証」を完了すると自動で有効化され、評判記録が始まります。未激活の間はロックと额度の割当はできますが、受注とマッチングはできません。",
  "requires master identity verification (证件 + 刷脸). 主身份完成实名认证后自动激活。": "requires master identity verification（身分証 + 顔認証）。主アイデンティティの実名認証が完了すると自動で有効化されます。",
  "本人确认对该 agent 的交付与证据责任边界负责；资金不托管；未声明能力不接单；虚假指标视为违约。": "本人が本 agent の納品と証跡の責任境界に責任を持つことを確認します。資金は預託しません。未申告の能力では受注しません。虚偽の指標は违约とみなします。",
  "P1 就绪：身份/责任/履约能力已界定且可对端核验，可安全进入发现与成交。": "P1 就绪：アイデンティティ・責任・履行能力が画定され、相手側が検証できます。安全にディスカバリと成約へ進めます。",
  "P1 未就绪：存在 gaps，对端不应将其视为可履约商家/企业（用户亦应补齐绑定）。": "P1 未就绪：gap が存在するため、相手側はこれを履行可能な商家・企業とみなすべきではありません（ユーザーも紐付けを補う必要があります）。",
  "核验基于目录行、名片、边界哈希、责任签认与信誉记录；boundary_complete 与 ack 均不可仅靠客户端自报。": "検証はディレクトリ行・名刺・境界ハッシュ・責任署名・評判記録に基づきます。boundary_complete と ack はクライアントの自己申告だけに依拠できません。",
  "配对接入": "ペアリング",
  "配对码接入": "ペアリングコードで接続",
  "agent 发起接入时会拿到一串配对码，把它给你；你在这里确认一次，它自己把凭据领走。你不用把密钥抄给它，它也不该向你要密钥。": "エージェントが接続を開始するとペアリングコードが発行され、あなたに提示されます。ここで一度確認すれば、資格情報はエージェント自身が受け取りに来ます。鍵を書き写して渡す必要はなく、エージェントが鍵を求めるべきでもありません。",
