  "API Key 已经放进这次配对，等它自己来领（只发一次，本页不会显示这串密钥）。": "APIキーはこのペアリングに預けてあり、エージェント自身が受け取りに来ます（一度きりで、このページに鍵は表示されません）。",
  "授权额度（可选）": "与信枠の付与（任意）",
  "批准之后 agent 只有身份、还动不了钱。在这里划一次额度并签名，钱钥匙会跟身份一起交给它。": "承認した時点では、エージェントは身元だけで資金は動かせません。ここで一度だけ与信枠を設定して署名すると、資金キーが身元と一緒に渡されます。",
