  "agent 用 KARMA_AGENT_ID + KARMA_API_KEY 完成身份识别；用 KARMA_RUNTIME_KEY 请求付款码、提交回执、申请结算。": "agent は KARMA_AGENT_ID + KARMA_API_KEY で身元を示し、KARMA_RUNTIME_KEY で支払いコードの要求・レシート提出・決済申請を行います。",
  "对方成交前会查 p1-status；这就是 Karma 对这笔收付的验证依据。": "相手方は成約前に p1-status を確認します。これが Karma によるこの収支の検証根拠です。",
  "不再需要这个 agent 时，用下面「停用并销毁密钥」——Karma 托管的运行密钥会一并销毁。": "この agent が不要になったら、下の「無効化して鍵を破棄」を使ってください。Karma が保管するランタイムキーも一緒に破棄されます。",
  "这个身份还打不开复核队列：队列只对": "この身元ではまだレビューキューを開けません。開けるのは ",
  "这个身份还打不开复核队列：队列只对复核岗（verifier）开放。复核岗有两条路：平台点名开通，或者平台开放申请后用已锁仓的 USDC 质押开通 —— 押金一走，这个岗就自动停。": "この身元はまだレビューキューを開けません。キューはレビュー担当（verifier）だけのものです。入る道は二つ：運営が指名するか、プラットフォームが開放したあと、すでにロック済みの USDC を供託して開くか。供託がなくなれば、その役割は止まります。",
  "，再由本人建一张 verifier 类身份档案。": "その後、本人が verifier 種別の身元プロフィールを作成します。",
  "链上锁仓未启用：当前锁仓走台账模式，没有真实 USDC 进入合约。": "オンチェーンロックは有効になっていません。現在のロックは台帳モードで、実際の USDC はコントラクトに入りません。",
  "授权额度模式未启用：当前走链上锁仓模式。": "与信枠モードは有効になっていません。現在はオンチェーンロックモードで動作します。",
