  " · 结算账户未配置：暂时需要 agent 自行提交结算": " · 決済アカウントが未設定です。当面は agent が自分で決済を申請する必要があります",
  "链上锁仓未启用（缺少配置：{0}）：当前锁仓走台账模式，没有真实 USDC 进入合约。": "オンチェーンロックは有効になっていません（未設定: {0}）。現在のロックは台帳モードで、実際の USDC はコントラクトに入りません。",
  "授权额度模式未启用（缺少配置：{0}）：当前走链上锁仓模式。": "与信枠モードは有効になっていません（未設定: {0}）。現在はオンチェーンロックモードで動作します。",
