  "没有待确认的接入请求，先点「读取已有密钥」": "確認待ちの接続リクエストはありません。先に「既存の鍵を読み込む」を押してください",
  "匹配码是 8 位（形如 XXXX-XXXX），请照 agent 显示的原样抄一遍": "照合コードは 8 文字です（XXXX-XXXX の形式）。agent の表示どおりに正確に入力してください",
